import 'dart:async';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';
import 'package:plugin_platform_interface/plugin_platform_interface.dart';

export 'src/image_cropper_platform_interface.dart';
export 'src/crop_options.dart';
export 'src/crop_result.dart';

/// Main entry point for the image cropper plugin.
class ImageCropper {
  ImageCropper._();

  /// Crops an image file using native platform implementations.
  ///
  /// [sourcePath] - Path to the source image file.
  /// [options] - Configuration options for cropping (aspect ratio, UI customization, etc.).
  ///
  /// Returns a [CroppedFile] containing the path to the cropped image,
  /// or null if the user cancelled the operation.
  static Future<CroppedFile?> cropImage({
    required String sourcePath,
    CropOptions? options,
  }) async {
    return ImageCropperPlatform.instance.cropImage(
      sourcePath: sourcePath,
      options: options ?? const CropOptions(),
    );
  }

  /// Crops an image from raw bytes using native platform implementations.
  ///
  /// [imageData] - Raw image bytes.
  /// [options] - Configuration options for cropping.
  /// [format] - The format of the input image data.
  ///
  /// Returns a [CroppedFile] containing the cropped image bytes,
  /// or null if the user cancelled the operation.
  static Future<CroppedFile?> cropImageFromBytes({
    required Uint8List imageData,
    CropOptions? options,
    ImageFormat format = ImageFormat.jpeg,
  }) async {
    return ImageCropperPlatform.instance.cropImageFromBytes(
      imageData: imageData,
      options: options ?? const CropOptions(),
      format: format,
    );
  }
}

/// Platform interface for image cropping.
abstract class ImageCropperPlatform extends PlatformInterface {
  ImageCropperPlatform() : super(token: _token);

  static final Object _token = Object();

  static ImageCropperPlatform _instance = MethodChannelImageCropper();

  static ImageCropperPlatform get instance => _instance;

  static set instance(ImageCropperPlatform instance) {
    PlatformInterface.verifyToken(instance, _token);
    _instance = instance;
  }

